// Convert input polygons to CGAL polygons
internal::Polygon_2 cgalP1, cgalP2;
for (const auto& p : P1.vectorPoints()) {
    cgalP1.push_back(internal::Point_2(p.x(), p.y()));
}
for (const auto& p : P2.vectorPoints()) {
    cgalP2.push_back(internal::Point_2(p.x(), p.y()));
}

// Compute difference using CGAL
internal::Pwh_list_2 difference;
CGAL::difference(cgalP1, cgalP2, std::back_inserter(difference));

// Convert result back to PolygonWithHoles2d
std::vector<PolygonWithHoles2d> result;
for (const auto& pwh : difference) {
    PolygonWithHoles2d polyWithHoles;

    // Convert outer boundary
    std::vector<Point2d> outerBoundary;
    for (const auto& p : pwh.outer_boundary()) {
        double x, y;
        internal::getCoordinates(p, x, y);
        outerBoundary.emplace_back(x, y);
    }
    polyWithHoles.setOuterBoundary(Polygon2d(outerBoundary));

    // Convert holes
    for (const auto& hole : pwh.holes()) {
        std::vector<Point2d> holeBoundary;
        for (const auto& p : hole) {
            double x, y;
            internal::getCoordinates(p, x, y);
            holeBoundary.emplace_back(x, y);
        }
        polyWithHoles.addHole(Polygon2d(holeBoundary));
    }

    result.push_back(polyWithHoles);
}

return result;

